//! Liqlip — wiring hub (coordinator file, CLAUDE.md hard rule 7): `run()`, plugins, the
//! `liq` URI scheme, managed state, the three pre-created windows, the tray, the order of
//! `setup()` (ARCHITECTURE §3) and the registration of every §9.6 command.
//! W1 agents do not edit this file — they hand the coordinator a snippet.

mod autostart;
mod capture;
mod content;
mod events;
mod fsx;
mod hotkeys;
mod i18n_native;
mod import;
mod logx;
mod model;
mod ocr;
mod paste;
mod picker;
mod settings;
mod store;
mod theme;
mod tray;

use model::Bounds;
use tauri::{
    AppHandle, Manager, PhysicalPosition, PhysicalSize, RunEvent, WebviewUrl, WebviewWindow,
    WebviewWindowBuilder, WindowEvent,
};

/// Transparent margin around the shelf panel for its shadow (Liquid Tools `BLEED`).
const PICKER_BLEED: f64 = 72.0;

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    let app = tauri::Builder::default()
        // MUST be the first plugin (its docs): a second launch summons the running
        // instance's shelf and exits, instead of a second tray icon / hook set.
        .plugin(tauri_plugin_single_instance::init(|app, _args, _cwd| {
            picker::summon(app);
        }))
        .plugin(tauri_plugin_autostart::init(
            tauri_plugin_autostart::MacosLauncher::LaunchAgent,
            None,
        ))
        .plugin(tauri_plugin_dialog::init())
        .plugin(tauri_plugin_opener::init())
        // W1-D: re-send layout/open to a webview that loaded after the shelf was summoned
        // (summon within the first second after launch).
        .on_page_load(|webview, payload| {
            if matches!(payload.event(), tauri::webview::PageLoadEvent::Finished) {
                picker::on_page_load(webview.app_handle(), webview.label());
            }
        })
        // Media for the webviews: `http://liq.localhost/{thumb,media,icon}/<id>` (§9.8),
        // like Liquid Tools' `ltthumb`. The file read runs off the WebView2 thread; the
        // version lives in `?v=`, so responses are immutable.
        .register_asynchronous_uri_scheme_protocol("liq", |ctx, request, responder| {
            let app = ctx.app_handle().clone();
            let path = request.uri().path().to_string();
            tauri::async_runtime::spawn_blocking(move || {
                let resp = match store::serve_uri(&app, &path) {
                    Some((mime, bytes)) => tauri::http::Response::builder()
                        .status(200)
                        .header("Content-Type", mime)
                        .header("Cache-Control", "public, max-age=31536000, immutable")
                        .header("Access-Control-Allow-Origin", "*")
                        .body(bytes),
                    None => tauri::http::Response::builder()
                        .status(404)
                        .header("Access-Control-Allow-Origin", "*")
                        .body(Vec::new()),
                };
                if let Ok(resp) = resp {
                    responder.respond(resp);
                }
            });
        })
        .setup(|app| {
            let handle = app.handle().clone();
            let data_dir = app.path().app_data_dir()?;

            // 1. Log file + panic hook first — everything below may warn.
            logx::init_at(&data_dir.join("logs"));

            // 2. Plugins are registered on the builder above.

            // 3. Settings, then launch-on-login reconciliation.
            app.manage(settings::SettingsStore::load(&data_dir));
            settings::apply_startup(&handle);
            let current = settings::get(&handle);

            // 4. Store — managed BEFORE any window exists: webviews invoke commands as
            //    soon as they load, and `State<…>` before `manage()` panics.
            let store = store::Store::open(&data_dir).map_err(|e| {
                logx::warn("store", &format!("open failed: {e}"));
                e
            })?;
            app.manage(store);
            store::init(&handle);

            // 5. Background modules.
            capture::start(&handle);
            paste::init(&handle);
            ocr::start(&handle);

            // 6. Windows — all pre-created hidden, only shown/hidden later (CLAUDE.md
            //    hard rule 2: a lazy build from a hotkey/tray thread deadlocks Windows).
            build_windows(&handle, &current)?;
            picker::init(&handle);

            // 7. Global hotkeys.
            for e in hotkeys::start(&handle, &current.hotkeys) {
                logx::warn("hotkeys", &format!("start: {} {:?}", e.field, e.code));
            }

            // 8. Tray.
            tray::build(&handle)?;

            // 9. Native theme of the (now existing) windows.
            theme::apply(&handle, current.general.theme);

            // 10. First run → onboarding in the settings window.
            if !current.general.onboarding_done {
                picker::show_settings(&handle, Some("onboarding"));
            }
            Ok(())
        })
        .invoke_handler(tauri::generate_handler![
            // settings (W0, implemented)
            settings::settings_get,
            settings::settings_set,
            settings::app_info,
            settings::open_path,
            settings::pick_exe,
            // store (W1-A)
            store::commands::clips_list,
            store::commands::clips_counts,
            store::commands::clip_detail,
            store::commands::clip_set_favorite,
            store::commands::clip_move_favorite,
            store::commands::clip_set_folder,
            store::commands::clip_rename,
            store::commands::clip_update_text,
            store::commands::clip_create_text,
            store::commands::clips_delete,
            store::commands::clips_undo,
            store::commands::clips_delete_recent,
            store::commands::clips_clear,
            store::commands::folders_list,
            store::commands::folder_create,
            store::commands::folder_rename,
            store::commands::folder_move,
            store::commands::folder_delete,
            store::commands::snippets_list,
            store::commands::snippet_save,
            store::commands::snippet_delete,
            store::commands::snippet_mark_used,
            store::commands::snippet_move,
            store::commands::apps_list,
            store::commands::storage_stats,
            // paste (W1-C)
            paste::commands::clip_paste,
            paste::commands::clip_copy,
            paste::commands::text_paste,
            paste::commands::text_copy,
            paste::commands::clipboard_text,
            paste::commands::clip_open,
            paste::commands::clip_open_with,
            paste::commands::clip_reveal,
            paste::commands::clip_drag_out,
            paste::commands::stack_get,
            paste::commands::stack_add,
            paste::commands::stack_remove,
            paste::commands::stack_move,
            paste::commands::stack_reverse,
            paste::commands::stack_clear,
            paste::commands::stack_paste_all,
            paste::commands::stack_paste_next,
            // capture (W1-B)
            capture::commands::capture_status,
            capture::commands::capture_pause,
            capture::commands::capture_resume,
            capture::commands::capture_ignore_next,
            capture::commands::capture_set_collect,
            capture::commands::apps_running,
            // picker (W1-D)
            picker::commands::picker_hide,
            picker::commands::picker_make_interactive,
            picker::commands::picker_target,
            picker::commands::settings_open,
            picker::commands::monitors_list,
            // hotkeys (W1-D)
            hotkeys::commands::hotkey_record_start,
            hotkeys::commands::hotkey_record_stop,
            // ocr (W2-A)
            ocr::commands::ocr_status,
            ocr::commands::ocr_reindex,
            ocr::commands::clip_ocr,
            // import (W2-B)
            import::commands::import_lt_probe,
            import::commands::import_lt_run,
            import::commands::backup_export,
            import::commands::backup_import,
        ])
        .build(tauri::generate_context!())
        .expect("error while building Liqlip");

    app.run(|app, event| {
        if let RunEvent::Exit = event {
            // W1-B: RemoveClipboardFormatListener + stop the capture threads.
            capture::stop();
            if let Some(win) = app.get_webview_window(events::SETTINGS) {
                save_settings_bounds(&win);
            }
        }
    });
}

/// `setup()` step 6. Geometry/visibility after this point belongs to `picker` (W1-D);
/// these are only the creation parameters of ARCHITECTURE §2.
fn build_windows(app: &AppHandle, current: &model::Settings) -> tauri::Result<()> {
    // Shelf: transparent, frameless, always-on-top, no taskbar button. Sized for the
    // centre layout + bleed; `picker` re-docks it on every summon.
    let picker = WebviewWindowBuilder::new(app, events::PICKER, WebviewUrl::App("picker.html".into()))
        .title("Liqlip")
        .transparent(true)
        .decorations(false)
        .shadow(false)
        .always_on_top(true)
        .skip_taskbar(true)
        .resizable(false)
        .focusable(true)
        .visible(false)
        .inner_size(760.0 + 2.0 * PICKER_BLEED, 640.0 + 2.0 * PICKER_BLEED)
        // WebView2's own drag-drop handler would swallow the native OLE drag-out of cards
        // (Tauri docs: disabling it is required for HTML5 drag and drop on Windows).
        .disable_drag_drop_handler()
        .build()?;

    // HUD: never activated (WS_EX_NOACTIVATE via `focusable(false)`, tao), click-through.
    let hud = WebviewWindowBuilder::new(app, events::HUD, WebviewUrl::App("hud.html".into()))
        .title("Liqlip HUD")
        .transparent(true)
        .decorations(false)
        .shadow(false)
        .always_on_top(true)
        .skip_taskbar(true)
        .resizable(false)
        .focusable(false)
        .visible(false)
        .inner_size(440.0, 112.0) // = picker::geometry::HUD_SIZE: HUD capsule + shadow bleed
        .build()?;
    hud.set_ignore_cursor_events(true)?;

    // Settings: an ordinary Windows window with the system title bar.
    let lang = i18n_native::resolve(current.general.language);
    let settings_win =
        WebviewWindowBuilder::new(app, events::SETTINGS, WebviewUrl::App("settings.html".into()))
            .title(i18n_native::tr(lang, i18n_native::Key::SettingsWindowTitle))
            .decorations(true)
            .resizable(true)
            .min_inner_size(720.0, 520.0)
            .inner_size(960.0, 680.0)
            .center()
            .visible(false)
            .disable_drag_drop_handler()
            .build()?;
    if let Some(b) = current.window.settings_bounds {
        restore_settings_bounds(&settings_win, b);
    }

    // Alt+F4 / the close button never destroys a pre-created window (a Liquid Tools bug
    // on its shelf): hide instead. Settings also remembers its geometry.
    for win in [&picker, &hud] {
        let w = win.clone();
        win.on_window_event(move |event| {
            if let WindowEvent::CloseRequested { api, .. } = event {
                api.prevent_close();
                let _ = w.hide();
            }
        });
    }
    {
        let w = settings_win.clone();
        settings_win.on_window_event(move |event| {
            if let WindowEvent::CloseRequested { api, .. } = event {
                api.prevent_close();
                save_settings_bounds(&w);
                let _ = w.hide();
            }
        });
    }
    // OS light/dark switch: re-broadcast the resolved theme (pref = system) and re-pick
    // the tray icon variant. One window is enough to hear it.
    {
        let app = app.clone();
        picker.on_window_event(move |event| match event {
            WindowEvent::ThemeChanged(_) => {
                let pref = settings::get(&app).general.theme;
                if pref == model::ThemePref::System {
                    theme::emit_changed(&app, pref);
                }
                tray::refresh(&app);
            }
            // W2-D: the tray glyph size follows the taskbar DPI.
            WindowEvent::ScaleFactorChanged { .. } => tray::refresh(&app),
            _ => {}
        });
    }
    // The settings title follows the language.
    settings::subscribe(app, {
        let w = settings_win.clone();
        move |old, new| {
            if old.general.language != new.general.language {
                let lang = i18n_native::resolve(new.general.language);
                let _ = w.set_title(i18n_native::tr(lang, i18n_native::Key::SettingsWindowTitle));
            }
        }
    });
    Ok(())
}

/// Persist the settings window's outer position + inner size (physical px). Skipped while
/// minimized / maximized so the restored geometry is the normal one.
fn save_settings_bounds(win: &WebviewWindow) {
    if win.is_minimized().unwrap_or(true) || win.is_maximized().unwrap_or(true) {
        return;
    }
    let (Ok(pos), Ok(size)) = (win.outer_position(), win.inner_size()) else { return };
    let bounds = Bounds { x: pos.x, y: pos.y, w: size.width as i32, h: size.height as i32 };
    settings::patch_window_bounds(win.app_handle(), bounds);
}

/// Restore saved geometry only if its title-bar strip is still on some monitor
/// (a disconnected monitor must not strand the window off-screen).
fn restore_settings_bounds(win: &WebviewWindow, b: Bounds) {
    let on_screen = win.available_monitors().unwrap_or_default().iter().any(|m| {
        let (p, s) = (m.position(), m.size());
        let (mx0, my0) = (p.x, p.y);
        let (mx1, my1) = (p.x + s.width as i32, p.y + s.height as i32);
        // A 100×30 px grab area at the window's top-left must be visible.
        b.x + 100 > mx0 && b.x < mx1 - 100 && b.y >= my0 && b.y + 30 <= my1
    });
    if !on_screen {
        return;
    }
    let _ = win.set_size(PhysicalSize::new(b.w.max(1) as u32, b.h.max(1) as u32));
    let _ = win.set_position(PhysicalPosition::new(b.x, b.y));
}
